CREATE SCHEMA IF NOT EXISTS app_private;
REVOKE ALL ON SCHEMA app_private FROM PUBLIC;
GRANT USAGE ON SCHEMA app_private TO anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.sync_bundle_gallery(),public.record_order_status_history(),public.audit_profile_privacy(),public.audit_privacy_grant() FROM PUBLIC,anon,authenticated;
ALTER FUNCTION public.set_bundle_primary_image(uuid) SET SCHEMA app_private;
ALTER FUNCTION public.curated_list_follow_counts(uuid[]) SET SCHEMA app_private;
ALTER FUNCTION public.claim_price_alerts() SET SCHEMA app_private;
ALTER FUNCTION public.touch_my_presence() SET SCHEMA app_private;
ALTER FUNCTION public.get_user_presence(uuid) SET SCHEMA app_private;
ALTER FUNCTION public.admin_move_category(uuid,text) SET SCHEMA app_private;
ALTER FUNCTION public.request_my_data_deletion() SET SCHEMA app_private;
ALTER FUNCTION public.admin_complete_data_deletion(uuid) SET SCHEMA app_private;
CREATE FUNCTION public.set_bundle_primary_image(_image_id uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT app_private.set_bundle_primary_image(_image_id); $$;
CREATE FUNCTION public.curated_list_follow_counts(_list_ids uuid[]) RETURNS TABLE(list_id uuid,follow_count bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM app_private.curated_list_follow_counts(_list_ids); $$;
CREATE FUNCTION public.claim_price_alerts() RETURNS TABLE(product_id uuid,current_price numeric,target_price numeric) LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM app_private.claim_price_alerts(); $$;
CREATE FUNCTION public.touch_my_presence() RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT app_private.touch_my_presence(); $$;
CREATE FUNCTION public.get_user_presence(_user_id uuid) RETURNS TABLE(is_online boolean,last_seen_at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM app_private.get_user_presence(_user_id); $$;
CREATE FUNCTION public.admin_move_category(_id uuid,_direction text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT app_private.admin_move_category(_id,_direction); $$;
CREATE FUNCTION public.request_my_data_deletion() RETURNS public.data_deletion_requests LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT app_private.request_my_data_deletion(); $$;
CREATE FUNCTION public.admin_complete_data_deletion(_request_id uuid) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT app_private.admin_complete_data_deletion(_request_id); $$;
REVOKE ALL ON FUNCTION public.set_bundle_primary_image(uuid),public.claim_price_alerts(),public.touch_my_presence(),public.get_user_presence(uuid),public.admin_move_category(uuid,text),public.request_my_data_deletion(),public.admin_complete_data_deletion(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_bundle_primary_image(uuid),public.claim_price_alerts(),public.touch_my_presence(),public.get_user_presence(uuid),public.admin_move_category(uuid,text),public.request_my_data_deletion(),public.admin_complete_data_deletion(uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.curated_list_follow_counts(uuid[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.curated_list_follow_counts(uuid[]) TO anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.validate_review_comment_target(),public.validate_deletion_request(),public.reset_favorite_price_alert() FROM PUBLIC,anon,authenticated;
NOTIFY pgrst,'reload schema';